/** Exact price-list row only — use for formal quotes (no nearest-kW fallback). */
export function lookupExactPrice(
  model: string,
  laserSource: string,
  kw: number
): { list: number; net: number } | null {
  const laser = normalizeLaser(laserSource)
  const modelKey = normalizeModel(model)
  return PRICE_TABLE[`${modelKey}|${laser}|${kw}`] ?? null
}

/** Nearest sheet row — dealer price-check neighbors only; not for saved quotes. */
export function lookupPrice(
  model: string,
  laserSource: string,
  kw: number
): { list: number; net: number } | null {
  const laser = normalizeLaser(laserSource)
  const modelKey = normalizeModel(model)
  const exact = PRICE_TABLE[`${modelKey}|${laser}|${kw}`]
  if (exact) return exact
  const otherLaser = laser === 'IPG' ? 'Raycus' : 'IPG'
  const other = PRICE_TABLE[`${modelKey}|${otherLaser}|${kw}`]
  if (other) return other
  const fp = Object.entries(PRICE_TABLE).filter(([k]) => k.startsWith(`${modelKey}|${laser}|`))
  if (fp.length > 0) return nearestKw(fp, kw)
  const fo = Object.entries(PRICE_TABLE).filter(([k]) => k.startsWith(`${modelKey}|${otherLaser}|`))
  if (fo.length > 0) return nearestKw(fo, kw)
  return null
}

function nearestKw(entries: [string, { list: number; net: number }][], target: number) {
  let best: { list: number; net: number } | null = null
  let bestDiff = Infinity
  for (const [k, v] of entries) {
    const diff = Math.abs(parseInt(k.split('|')[2]) - target)
    if (diff < bestDiff) { bestDiff = diff; best = v }
  }
  return best
}

export function normalizeModel(raw: string): string {
  // Strip any embedded power rating (e.g. "60kW") — power is a separate field
  const s = raw.trim().replace(/\b\d+\s*kW\b/gi, '').replace(/\s+/g, ' ').trim()

  if (/demo\s*fast/i.test(s)) { const fmt = s.match(/(\d{4})/)?.[1] ?? '4020'; return `FAST ${fmt}` }

  // Named multi-word families — match before generic fallback
  const pbM = s.match(/PLUS\s+Bevel\s+(\d{4,5})/i); if (pbM) return `PLUS Bevel ${pbM[1]}`
  const peM = s.match(/PLUS\s+Evo\s+(\d{4,5})/i);   if (peM) return `PLUS Evo ${peM[1]}`
  const fhdM = s.match(/\bFHD\s+(\d{4,5})\b/i);      if (fhdM) return `Fiber HD ${fhdM[1]}`
  const fhM = s.match(/Fiber\s+HD\s+(\d{4,5})/i);   if (fhM) return `Fiber HD ${fhM[1]}`
  const ftM = s.match(/Fiber\s+Tube\s+TL(\d+)/i);   if (ftM) return `Fiber Tube TL${ftM[1]}`

  for (const fam of ['FAST', 'XME', 'XMF', 'LME']) {
    const m = s.match(new RegExp(`\\b${fam}\\s+(\\d{4,5})`, 'i'))
    if (m) return `${fam} ${m[1]}`
  }

  // Generic fallback: "FAMILY NNNN"
  const g = s.match(/([A-Za-z][A-Za-z ]+?)\s+(\d{4,5})/)
  if (g) return `${g[1].trim().toUpperCase()} ${g[2]}`
  return s
}

export function normalizeLaser(raw: string): 'IPG' | 'Raycus' {
  const s = raw.toLowerCase()
  return /raycus/.test(s) || /racus/.test(s) ? 'Raycus' : 'IPG'
}

export function parseKw(power: string): number {
  const m = power.match(/(\d+(?:\.\d+)?)\s*k?w/i)
  return m ? Math.round(parseFloat(m[1])) : 6
}

